def file_name_check(name):
    ascii_digits = set("0123456789")
    ascii_letters = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")

    if sum(1 for c in name if c in ascii_digits) > 3:
        return 'No'

    if name.count('.') != 1:
        return 'No'

    prefix, extension = name.split('.')

    if not prefix or prefix[0] not in ascii_letters:
        return 'No'

    if extension not in ('txt', 'exe', 'dll'):
        return 'No'

    return 'Yes'

def order_by_points(nums):
    def digit_points(n):
        digits = str(abs(n))
        if n < 0:
            return -int(digits[0]) + sum(int(d) for d in digits[1:])
        return sum(int(d) for d in digits)

    return sorted(nums, key=digit_points)

