def _split_segments(line):
    """Split on ';' outside double-quoted regions.

    Inside quotes, a backslash before a double quote is an escape, so \\"
    does not close the quoted value.
    """
    segments = []
    buf = []
    in_quote = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '\\' and i + 1 < n and line[i + 1] == '"':
                buf.append('\\"')
                i += 2
                continue
            if ch == '"':
                in_quote = False
            buf.append(ch)
        else:
            if ch == '"':
                in_quote = True
                buf.append(ch)
            elif ch == ';':
                segments.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        i += 1
    if in_quote:
        raise ValueError("unterminated quoted value")
    segments.append(''.join(buf))
    return segments


def _parse_quoted(s):
    """Parse a quoted value beginning at s[0] == '"'.

    Inside quotes, \\" yields a literal quote and the backslash is dropped.
    Escaped quotes do not close the value. Only whitespace may follow the
    closing quote.
    """
    out = []
    i = 1
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '\\' and i + 1 < n and s[i + 1] == '"':
            out.append('"')
            i += 2
            continue
        if ch == '"':
            if s[i + 1:].strip():
                raise ValueError(f"unexpected text after quoted value: {s[i + 1:]!r}")
            return ''.join(out)
        out.append(ch)
        i += 1
    raise ValueError("unterminated quoted value")


def _parse_segment(segment):
    seg = segment.strip()
    if not seg:
        return None

    if '=' not in seg:
        key, value = seg, True
    else:
        key, _, rest = seg.partition('=')
        key = key.strip()
        rest = rest.lstrip()
        if rest.startswith('"'):
            value = _parse_quoted(rest)
        else:
            if '"' in rest:
                raise ValueError(f"unexpected quote in bare value: {rest!r}")
            value = rest.strip()

    if not key:
        raise ValueError(f"empty key in segment: {segment!r}")
    if '"' in key:
        raise ValueError(f"unexpected quote in key: {key!r}")
    return key, value


def parse_kv(line):
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by ';'.
    - 'key=value' maps key to the value (string).
    - A bare 'key' maps to True.
    - A double-quoted value may contain ';' and whitespace.
    - Inside quotes, \\" is a literal quote and does not close the value.
    - An unterminated quoted value raises ValueError.
    """
    result = {}
    for segment in _split_segments(line):
        parsed = _parse_segment(segment)
        if parsed is None:
            continue
        key, value = parsed
        result[key] = value
    return result

