        raise ValueError("empty string is not a valid Roman numeral")
    if any(ch not in _CHAR_VALUES for ch in s):
        raise ValueError(
            f"invalid characters in Roman numeral {s!r}; only uppercase I, V, X, L, C, D, M are allowed"
        )
    if not _ROMAN_PATTERN.fullmatch(s):
        raise ValueError(f"invalid Roman numeral {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _CHAR_VALUES[ch]
        if i + 1 < len(s) and value < _CHAR_VALUES[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999:
        raise ValueError(f"Roman numeral {s!r} is out of range")
    return total

def parse_kv(line):
    result = {}
    n = len(line)
    i = 0

    while True:
        # Skip whitespace before a key.
        while i < n and line[i].isspace():
            i += 1
        if i >= n:
            break
        # Skip empty segments such as a trailing or doubled semicolon.
        if line[i] == ';':
            i += 1
            continue

        # Read the key up to '=', ';', or end of line.
        start = i
        while i < n and line[i] not in '=;':
            i += 1
        key = line[start:i].strip()
        if not key:
            raise ValueError("empty key in config line")

        # Bare key: maps to True.
        if i >= n or line[i] == ';':
            result[key] = True
            if i < n:
                i += 1
            continue

        # Key with a value: line[i] is '='.
        i += 1
        while i < n and line[i].isspace():
            i += 1

        if i < n and line[i] == '"':
            # Quoted value; may contain semicolons.
            i += 1
            buf = []
            closed = False
            while i < n:
                c = line[i]
                if c == '\\' and i + 1 < n and line[i + 1] == '"':
                    # Escaped quote: literal '"', backslash dropped.
                    buf.append('"')
                    i += 2
                    continue
                if c == '"':
                    closed = True
                    i += 1
                    break
                buf.append(c)
                i += 1
            if not closed:
                raise ValueError(f"unclosed quote in value for key {key!r}")
            value = ''.join(buf)

            # Only whitespace may follow a closing quote, then ';' or end.
            while i < n and line[i].isspace():
                i += 1
            if i < n and line[i] != ';':
                raise ValueError(f"unexpected text after quoted value for key {key!r}")
            if i < n:
                i += 1
        else:
            # Unquoted value: runs to the next semicolon.
            start = i
            while i < n and line[i] != ';':
                i += 1
            value = line[start:i].strip()
            if i < n:
                i += 1

        result[key] = value

    return result

def _split_fields(line):
    """Split on ';' that are outside double-quoted regions.

    Backslash-escaped quotes (\\") inside a quoted region do not close it.
    The escape sequences are preserved here and resolved later by _unquote.
    """
    fields = []
    buf = []
    in_quote = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quote:
            if ch == '\\' and i + 1 < n and line[i + 1] == '"':
                buf.append('\\"')
                i += 2
                continue
            if ch == '"':
                in_quote = False
            buf.append(ch)
        else:
            if ch == '"':
                in_quote = True
                buf.append(ch)
            elif ch == ';':
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        i += 1
    if in_quote:
        raise ValueError("unclosed double quote in line: %r" % line)
    fields.append(''.join(buf))
    return fields


def _unquote(raw):
    """Parse a raw value that starts with a double quote and return its content."""
    out = []
    i = 1
    n = len(raw)
    close = None
    while i < n:
        ch = raw[i]
        if ch == '\\' and i + 1 < n and raw[i + 1] == '"':
            out.append('"')
            i += 2
            continue
        if ch == '"':
            close = i
            break
        out.append(ch)
        i += 1
    if close is None:
        raise ValueError("unclosed double quote in value: %r" % raw)
    if raw[close + 1:].strip():
        raise ValueError("unexpected text after closing quote: %r" % raw)
    return ''.join(out)


def parse_kv(line):
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - 'key=value' maps key to value (string).
    - A bare key (no '=') maps to True.
    - Double-quoted values may contain semicolons and escaped quotes (\\").
    - An unclosed double quote raises ValueError.
    """
    result = {}
    for field in _split_fields(line):
        s = field.strip()
        if not s:
            continue
        idx = s.find('=')
        if idx == -1:
            key = s
            value = True
        else:
            key = s[:idx].strip()
            raw = s[idx + 1:].strip()
            if raw.startswith('"'):
                value = _unquote(raw)
            else:
                value = raw
        if not key:
            raise ValueError("empty key in field: %r" % field)
        result[key] = value
    return result

from typing import Dict, List, Tuple, Union

_Char = Tuple[str, bool]  # (character, came_from_quoted_section)


def _strip_unquoted(chars: List[_Char]) -> List[_Char]:
    """Trim whitespace from both ends, but never trim characters inside quotes."""
    start = 0
    end = len(chars)
    while start < end and not chars[start][1] and chars[start][0].isspace():
        start += 1
    while end > start and not chars[end - 1][1] and chars[end - 1][0].isspace():
        end -= 1
    return chars[start:end]


def parse_kv(line: str) -> Dict[str, Union[str, bool]]:
    """
    Parse a config line such as:  a=1; debug; msg="hi; there"

    - Fields are separated by semicolons that are not inside double quotes.
    - `key=value` maps to a string value; a bare `key` maps to True.
    - Double-quoted values may contain semicolons and whitespace.
    - Inside a quoted value, `\\"` is an escaped quote: the quote becomes part
      of the value, does not close the quoted section, and the backslash is
      removed.
    - An unterminated double quote raises ValueError.
    - Empty fields (e.g. from a trailing semicolon) are ignored.
    - If a key repeats, the last occurrence wins.
    """
    fields: List[List[_Char]] = []
    current: List[_Char] = []
    in_quote = False
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]
        if in_quote:
            if ch == "\\" and i + 1 < n and line[i + 1] == '"':
                current.append(('"', True))
                i += 2
                continue
            if ch == '"':
                in_quote = False
            else:
                current.append((ch, True))
        else:
            if ch == '"':
                in_quote = True
            elif ch == ";":
                fields.append(current)
                current = []
            else:
                current.append((ch, False))
        i += 1

    if in_quote:
        raise ValueError(f"unterminated double quote in config line: {line!r}")
    fields.append(current)

    result: Dict[str, Union[str, bool]] = {}
    for raw_field in fields:
        field = _strip_unquoted(raw_field)
        if not field:
            continue

        eq_index = None
        for idx, (c, quoted) in enumerate(field):
            if c == "=" and not quoted:
                eq_index = idx
                break

        if eq_index is None:
            key_chars = field
            value: Union[str, bool] = True
        else:
            key_chars = _strip_unquoted(field[:eq_index])
            value_chars = _strip_unquoted(field[eq_index + 1:])
            value = "".join(c for c, _ in value_chars)

        key = "".join(c for c, _ in key_chars)
        if not key:
            raise ValueError(f"empty key in config line: {line!r}")

        result[key] = value

    return result

def parse_kv(line):
    def split_entries(s):
        entries = []
        start = 0
        i = 0
        n = len(s)
        in_quote = False
        while i < n:
            ch = s[i]
            if in_quote:
                if ch == '\\' and i + 1 < n and s[i + 1] in '"\\':
                    i += 2
                    continue
                if ch == '"':
                    in_quote = False
            else:
                if ch == '"':
                    in_quote = True
                elif ch == ';':
                    entries.append(s[start:i])
                    start = i + 1
            i += 1
        if in_quote:
            raise ValueError("unterminated quoted value")
        entries.append(s[start:])
        return entries

    def parse_value(raw):
        if not raw.startswith('"'):
            return raw
        out = []
        i = 1
        n = len(raw)
        while i < n:
            ch = raw[i]
            if ch == '\\' and i + 1 < n and raw[i + 1] in '"\\':
                out.append(raw[i + 1])
                i += 2
                continue
            if ch == '"':
                if raw[i + 1:].strip():
                    raise ValueError("unexpected text after closing quote")
                return ''.join(out)
            out.append(ch)
            i += 1
        raise ValueError("unterminated quoted value")

    result = {}
    for entry in split_entries(line):
        entry = entry.strip()
        if not entry:
            continue
        key, eq, raw = entry.partition('=')
        key = key.strip()
        if not key:
            raise ValueError("empty key")
        if not eq:
            result[key] = True
        else:
            result[key] = parse_value(raw.strip())
    return result

