def _parse_quoted(raw):
    """Parse a double-quoted value starting at raw[0] == '"'.

    Returns (unescaped_value, remainder_after_closing_quote).
    Raises ValueError if the quote is never closed.
    """
    i = 1
    out = []
    n = len(raw)
    while i < n:
        c = raw[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("unterminated quoted value")
            out.append(raw[i + 1])
            i += 2
        elif c == '"':
            return ''.join(out), raw[i + 1:]
        else:
            out.append(c)
            i += 1
    raise ValueError("unterminated quoted value")


