            elif ch == '\\':
                escaped = True
            elif ch == '"':
                in_quote = False
        else:
            if ch == ';':
                tokens.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
                if ch == '"':
                    in_quote = True
    if in_quote:
        raise ValueError("unterminated quoted value")
    tokens.append(''.join(buf))

    # Pass 2: parse each entry into key/value.
    result = {}
    for tok in tokens:
        tok = tok.strip()
        if not tok:
            continue

        key, sep, raw = tok.partition('=')
        key = key.strip()
        if not key:
            raise ValueError("empty key in entry: %r" % tok)
        if '"' in key:
            raise ValueError("unexpected quote in key: %r" % key)

