        raw = raw.lstrip()
        if raw.startswith('"'):
            value, rest = _parse_quoted(raw)
            if rest.strip():
                raise ValueError("unexpected text after quoted value: %r" % rest.strip())
        else:
            if '"' in raw:
                raise ValueError("unexpected quote in value: %r" % raw)
