class TTLCache:
    """An LRU cache whose entries expire `ttl` seconds after they are written.

    The current time is always supplied by the caller via the `now` argument.
    An entry written at time `t` is considered expired when `now >= t + ttl`.
    """

    def __init__(self, capacity, ttl):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, expires_at); ordering is least- to most-recently used.
        self._data = OrderedDict()

    def _purge_expired(self, now):
        expired_keys = [
            key for key, (_, expires_at) in self._data.items()
            if now >= expires_at
        ]
        for key in expired_keys:
            del self._data[key]

    def put(self, key, value, now):
        self._purge_expired(now)
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = (value, now + self._ttl)
        while len(self._data) > self._capacity:
            self._data.popitem(last=False)

    def get(self, key, now):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if now >= expires_at:
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return value

    def size(self, now):
        self._purge_expired(now)
        return len(self._data)

