def evaluate(expr):
    """
    Evaluate an integer arithmetic expression.

    Supports + - * / % ^, unary minus, and parentheses. The operators follow
    these rules:
      * '/' and '%' truncate toward zero (C-style); '%' takes the sign of the
        dividend.
      * '^' is exponentiation and is right-associative. It binds tighter than
        unary minus, so -2^2 == -4.
      * Division or modulo by zero raises ZeroDivisionError.
      * A negative exponent raises ValueError unless the base is 1 or -1,
        since the result would not be an integer otherwise.

    Malformed input raises SyntaxError.
    """
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    value = parser.parse()
    return value


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() and ch in "0123456789":
            j = i
            while j < n and text[j] in "0123456789":
                j += 1
            tokens.append(("NUM", int(text[i:j])))
            i = j
        elif ch in "+-*/%^":
            tokens.append(("OP", ch))
            i += 1
        elif ch == "(":
            tokens.append(("LPAREN", ch))
            i += 1
        elif ch == ")":
            tokens.append(("RPAREN", ch))
            i += 1
        else:
            raise SyntaxError(f"Unexpected character {ch!r} at position {i}")
    tokens.append(("END", None))
    return tokens


def _c_div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def _c_mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    r = abs(a) % abs(b)
    return r if a >= 0 else -r


def _power(base, exp):
    if exp >= 0:
        return base ** exp
    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1
    if base == 0:
        raise ZeroDivisionError("zero raised to a negative power")
    raise ValueError("negative exponent yields a non-integer result")


class _Parser:
    # Grammar:
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/' | '%') unary)*
    #   unary   := '-' unary | power
    #   power   := primary ('^' unary)?
    #   primary := NUM | '(' expr ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect_end(self):
        if self.peek()[0] != "END":
            raise SyntaxError(f"Unexpected token {self.peek()[1]!r}")

    def parse(self):
        if self.peek()[0] == "END":
            raise SyntaxError("Empty expression")
        value = self.expr()
        self.expect_end()
        return value

    def expr(self):
        value = self.term()
        while self.peek() == ("OP", "+") or self.peek() == ("OP", "-"):
            op = self.advance()[1]
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.unary()
        while self.peek() in (("OP", "*"), ("OP", "/"), ("OP", "%")):
            op = self.advance()[1]
            rhs = self.unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def unary(self):
        if self.peek() == ("OP", "-"):
            self.advance()
            return -self.unary()
        return self.power()

    def power(self):
        base = self.primary()
        if self.peek() == ("OP", "^"):
            self.advance()
            exp = self.unary()
            return _power(base, exp)
        return base

    def primary(self):
        kind, val = self.peek()
        if kind == "NUM":
            self.advance()
            return val
        if kind == "LPAREN":
            self.advance()
            value = self.expr()
            if self.peek()[0] != "RPAREN":
                raise SyntaxError("Expected ')'")
            self.advance()
            return value
        if kind == "END":
            raise SyntaxError("Unexpected end of expression")
        raise SyntaxError(f"Unexpected token {val!r}")

def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            tokens.append(('num', int(text[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append((c, c))
            i += 1
        else:
            raise SyntaxError(f"invalid character {c!r} at position {i}")
    return tokens


def _c_div(a, b):
    """Integer division truncating toward zero (C semantics)."""
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _c_mod(a, b):
    """Remainder with the sign of the dividend (C semantics)."""
    return a - b * _c_div(a, b)


def _power(base, exp):
    if exp >= 0:
        return base ** exp
    # Negative exponent: only well-defined integer results for base in {1, -1}.
    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1
    if base == 0:
        raise ZeroDivisionError("0 raised to a negative power")
    raise ValueError("negative exponent yields a non-integer result")


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0] if self.pos < len(self.tokens) else None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_expr(self):
        value = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.advance()[0]
            rhs = self.parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term(self):
        value = self.parse_unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def parse_unary(self):
        if self.peek() == '-':
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == '^':
            self.advance()
            exp = self.parse_unary()  # right-associative; allows e.g. 2^-1
            return _power(base, exp)
        return base

    def parse_atom(self):
        kind = self.peek()
        if kind == 'num':
            return self.advance()[1]
        if kind == '(':
            self.advance()
            value = self.parse_expr()
            if self.peek() != ')':
                raise SyntaxError("expected ')'")
            self.advance()
            return value
        if kind is None:
            raise SyntaxError("unexpected end of expression")
        raise SyntaxError(f"unexpected token {kind!r}")

    def expect_end(self):
        if self.pos != len(self.tokens):
            raise SyntaxError(f"unexpected token {self.tokens[self.pos][0]!r}")


def evaluate(expr):
    if not isinstance(expr, str):
        raise SyntaxError("expression must be a string")
    tokens = _tokenize(expr)
    if not tokens:
        raise SyntaxError("empty expression")
    parser = _Parser(tokens)
    value = parser.parse_expr()
    parser.expect_end()
    return value

import re


_TOKEN_RE = re.compile(r"\s*(?:(\d+)|(.))")


def _tokenize(expr):
    tokens = []
    pos = 0
    n = len(expr)
    while pos < n:
        if expr[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(expr, pos)
        if m is None:
            raise SyntaxError(f"Unexpected character at position {pos}")
        if m.group(1) is not None:
            tokens.append(("NUM", int(m.group(1))))
        else:
            ch = m.group(2)
            if ch in "+-*/%^()":
                tokens.append(("OP", ch))
            else:
                raise SyntaxError(f"Invalid character {ch!r} at position {pos}")
        pos = m.end()
    tokens.append(("END", None))
    return tokens


def _c_div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def _c_mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    r = abs(a) % abs(b)
    return r if a >= 0 else -r


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i]

    def advance(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def expect_op(self, op):
        kind, val = self.peek()
        if kind == "OP" and val == op:
            self.advance()
        else:
            raise SyntaxError(f"Expected {op!r}")

    def parse(self):
        value = self.parse_expr()
        if self.peek()[0] != "END":
            raise SyntaxError("Unexpected token after expression")
        return value

    def parse_expr(self):
        value = self.parse_term()
        while True:
            kind, val = self.peek()
            if kind == "OP" and val in "+-":
                self.advance()
                rhs = self.parse_term()
                value = value + rhs if val == "+" else value - rhs
            else:
                return value

    def parse_term(self):
        value = self.parse_unary()
        while True:
            kind, val = self.peek()
            if kind == "OP" and val in "*/%":
                self.advance()
                rhs = self.parse_unary()
                if val == "*":
                    value = value * rhs
                elif val == "/":
                    value = _c_div(value, rhs)
                else:
                    value = _c_mod(value, rhs)
            else:
                return value

    def parse_unary(self):
        kind, val = self.peek()
        if kind == "OP" and val == "-":
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        kind, val = self.peek()
        if kind == "OP" and val == "^":
            self.advance()
            exp = self.parse_unary()  # right-associative; allows 2^-1
            if exp < 0:
                raise ValueError("negative exponent is not supported for integers")
            return base ** exp
        return base

    def parse_primary(self):
        kind, val = self.peek()
        if kind == "NUM":
            self.advance()
            return val
        if kind == "OP" and val == "(":
            self.advance()
            value = self.parse_expr()
            self.expect_op(")")
            return value
        raise SyntaxError("Expected number or '('")


def evaluate(expr):
    if not isinstance(expr, str):
        raise SyntaxError("Expression must be a string")
    tokens = _tokenize(expr)
    if tokens[0][0] == "END":
        raise SyntaxError("Empty expression")
    return _Parser(tokens).parse()

import csv
import io


def _parse_number(cell):
    try:
        return int(cell)
    except ValueError:
        return float(cell)


def column_stats(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))

    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = row
            break

    if header is None:
        raise KeyError(column)

    names = [name.strip() for name in header]
    if column not in names:
        raise KeyError(column)
    idx = names.index(column)

    values = []
    for row in reader:
        if idx >= len(row):
            continue
        cell = row[idx].strip()
        if not cell:
            continue
        values.append(_parse_number(cell))

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }

