        raise ValueError("negative exponent is not supported for integers")
    return base ** exp


class _Parser:
    # Grammar:
    #   expression := term (('+' | '-') term)*
    #   term       := unary (('*' | '/' | '%') unary)*
    #   unary      := '-' unary | power
    #   power      := primary ('^' unary)?        (right-associative)
    #   primary    := NUMBER | '(' expression ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _match_op(self, ops):
        tok = self._peek()
        if tok is not None and tok[0] == "OP" and tok[1] in ops:
            self.pos += 1
            return tok[1]
        return None

    def parse_expression(self):
        value = self.parse_term()
        while True:
            op = self._match_op("+-")
            if op is None:
                break
            rhs = self.parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term(self):
        value = self.parse_unary()
        while True:
            op = self._match_op("*/%")
            if op is None:
                break
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def parse_unary(self):
        if self._match_op("-") is not None:
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self._match_op("^") is not None:
            exp = self.parse_unary()
            return _c_pow(base, exp)
        return base

    def parse_primary(self):
        tok = self._peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")
        if tok[0] == "NUM":
            self.pos += 1
            return tok[1]
        if tok[0] == "OP" and tok[1] == "(":
            self.pos += 1
            value = self.parse_expression()
            if self._match_op(")") is None:
                raise SyntaxError("Expected ')'")
            return value
        raise SyntaxError(f"Unexpected token: {tok[1]!r}")

def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append((c, None))
            i += 1
        else:
            raise SyntaxError(f"unexpected character {c!r} at position {i}")
    tokens.append(('end', None))
    return tokens


def _c_div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return -q if (a < 0) != (b < 0) else q


def _c_mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    return a - b * _c_div(a, b)


def _int_pow(base, exp):
    if exp < 0:
        raise ValueError("negative exponent not supported for integer power")
    return base ** exp


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        value = self.expr()
        if self.peek() != 'end':
            raise SyntaxError("unexpected token after expression")
        return value

    def expr(self):
        value = self.term()
        while self.peek() in ('+', '-'):
            op = self.advance()[0]
            rhs = self.term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def term(self):
        value = self.unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def unary(self):
        if self.peek() == '-':
            self.advance()
            return -self.unary()
        return self.power()

    def power(self):
        base = self.primary()
        if self.peek() == '^':
            self.advance()
            exp = self.unary()  # right-associative; allows forms like 2^-1
            return _int_pow(base, exp)
        return base

    def primary(self):
        t = self.peek()
        if t == 'num':
            return self.advance()[1]
        if t == '(':
            self.advance()
            value = self.expr()
            if self.peek() != ')':
                raise SyntaxError("expected ')'")
            self.advance()
            return value
        raise SyntaxError("unexpected token")


def evaluate(expr):
    if not isinstance(expr, str):
        raise SyntaxError("expression must be a string")
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()

