def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() and ch in "0123456789":
            j = i
            while j < n and expr[j] in "0123456789":
                j += 1
            tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif ch in "+-*/%^()":
            tokens.append((ch, ch))
            i += 1
        else:
            raise SyntaxError(f"Unexpected character {ch!r} at position {i}")
    return tokens


def _c_div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _c_mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    return a - _c_div(a, b) * b


def _c_pow(base, exp):
    if exp < 0:
        raise ValueError("negative exponent is not supported for integer exponentiation")
    return base ** exp


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")
        self.pos += 1
        return tok

    def expect(self, kind):
        tok = self.advance()
        if tok[0] != kind:
            raise SyntaxError(f"Expected {kind!r} but found {tok[1]!r}")
        return tok

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Empty expression")
        value = self.expression()
        if self.peek() is not None:
            raise SyntaxError(f"Unexpected token {self.peek()[1]!r}")
        return value

    # expression := term (('+' | '-') term)*
    def expression(self):
        value = self.term()
        while True:
            tok = self.peek()
            if tok is None or tok[0] not in ("+", "-"):
                break
            self.advance()
            rhs = self.term()
            value = value + rhs if tok[0] == "+" else value - rhs
        return value

    # term := factor (('*' | '/' | '%') factor)*
    def term(self):
        value = self.factor()
        while True:
            tok = self.peek()
            if tok is None or tok[0] not in ("*", "/", "%"):
                break
            self.advance()
            rhs = self.factor()
            if tok[0] == "*":
                value = value * rhs
            elif tok[0] == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    # factor := '-' factor | power
    def factor(self):
        tok = self.peek()
        if tok is not None and tok[0] == "-":
            self.advance()
            return -self.factor()
        return self.power()

    # power := primary ('^' factor)?   (right-associative; exponent may be signed)
    def power(self):
        base = self.primary()
        tok = self.peek()
        if tok is not None and tok[0] == "^":
            self.advance()
            exp = self.factor()
            return _c_pow(base, exp)
        return base

    # primary := NUM | '(' expression ')'
    def primary(self):
        tok = self.advance()
        if tok[0] == "NUM":
            return tok[1]
        if tok[0] == "(":
            value = self.expression()
            self.expect(")")
            return value
        raise SyntaxError(f"Unexpected token {tok[1]!r}")


def evaluate(expr):
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()

from typing import Dict, List, Optional, Union

ACCEPTED_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices: Dict[str, int], coins: Dict[int, int]):
        self.prices: Dict[str, int] = dict(prices)
        self.coins: Dict[int, int] = {d: c for d, c in coins.items() if c > 0}
        self.inserted: List[int] = []

    def insert(self, coin: int) -> bool:
        if coin not in ACCEPTED_COINS:
            return False
        self.inserted.append(coin)
        return True

    def balance(self) -> int:
        return sum(self.inserted)

    def select(self, item: str) -> Union[List[int], str]:
        if item not in self.prices:
            return 'UNKNOWN'

        price = self.prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        # Inserted coins become part of the pool available for change.
        pool: Dict[int, int] = dict(self.coins)
        for coin in self.inserted:
            pool[coin] = pool.get(coin, 0) + 1

        change = self._make_change(bal - price, pool)
        if change is None:
            return 'NO_CHANGE'

        for coin in change:
            pool[coin] -= 1
        self.coins = {d: c for d, c in pool.items() if c > 0}
        self.inserted = []
        return change

    def cancel(self) -> List[int]:
        returned = list(self.inserted)
        self.inserted = []
        return returned

    @staticmethod
    def _make_change(amount: int, pool: Dict[int, int]) -> Optional[List[int]]:
        """Return the fewest coins from pool summing to amount, or None if impossible."""
        if amount == 0:
            return []

        denoms = sorted(d for d, c in pool.items() if c > 0 and d > 0)
        INF = float('inf')
        best = [INF] * (amount + 1)
        best[0] = 0
        picks: List[List[int]] = []

        # Bounded knapsack over denominations: best[a] = min coins to make a.
        for d in denoms:
            count = pool[d]
            new_best = [INF] * (amount + 1)
            pick = [0] * (amount + 1)
            for a in range(amount + 1):
                for j in range(min(count, a // d) + 1):
                    candidate = best[a - j * d] + j
                    if candidate < new_best[a]:
                        new_best[a] = candidate
                        pick[a] = j
            picks.append(pick)
            best = new_best

        if best[amount] == INF:
            return None

        # Reconstruct the chosen coins by walking the stages backwards.
        result: List[int] = []
        a = amount
        for idx in range(len(denoms) - 1, -1, -1):
            d = denoms[idx]
            j = picks[idx][a]
            result.extend([d] * j)
            a -= j * d

        return sorted(result, reverse=True)

def _tokenize(expr):
    """Split the expression into ('num', int) and ('op', str) tokens."""
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            tokens.append(("num", int(expr[start:i])))
        elif ch in "+-*/%^()":
            tokens.append(("op", ch))
            i += 1
        else:
            raise SyntaxError(f"invalid character {ch!r} at position {i}")
    return tokens


def _c_div(a, b):
    """Integer division truncating toward zero (C semantics)."""
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _c_mod(a, b):
    """Remainder whose sign follows the dividend (C semantics)."""
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def _power(base, exp):
    """Integer exponentiation. Negative exponents are rejected for all bases."""
    if exp < 0:
        raise ValueError("negative exponent is not supported for integer power")
    return base ** exp


class _Parser:
    # Grammar:
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/' | '%') unary)*
    #   unary   := '-' unary | power
    #   power   := primary ('^' unary)?        (right-associative)
    #   primary := NUMBER | '(' expr ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek_op(self):
        if self.pos < len(self.tokens):
            kind, value = self.tokens[self.pos]
            if kind == "op":
                return value
        return None

    def _advance(self):
        if self.pos >= len(self.tokens):
            raise SyntaxError("unexpected end of input")
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        value = self.parse_expr()
        if self.pos != len(self.tokens):
            raise SyntaxError("unexpected token after expression")
        return value

    def parse_expr(self):
        value = self.parse_term()
        while self._peek_op() in ("+", "-"):
            op = self._advance()[1]
            rhs = self.parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term(self):
        value = self.parse_unary()
        while self._peek_op() in ("*", "/", "%"):
            op = self._advance()[1]
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def parse_unary(self):
        if self._peek_op() == "-":
            self._advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self._peek_op() == "^":
            self._advance()
            exp = self.parse_unary()
            return _power(base, exp)
        return base

    def parse_primary(self):
        kind, value = self._advance()
        if kind == "num":
            return value
        if value == "(":
            inner = self.parse_expr()
            if self._peek_op() != ")":
                raise SyntaxError("expected ')'")
            self._advance()
            return inner
        raise SyntaxError(f"unexpected token {value!r}")


def evaluate(expr):
    """
    Evaluate an integer arithmetic expression supporting + - * / % ^,
    unary minus, and parentheses, without using eval.

    - Division and modulo truncate toward zero (C-style).
    - A negative exponent raises ValueError, including when the base is
      0, 1, or -1, rather than returning a truncated integer result.
    - Malformed input raises SyntaxError.
    """
    tokens = _tokenize(expr)
    if not tokens:
        raise SyntaxError("empty expression")
    return _Parser(tokens).parse()

class VendingMachine:
    DENOMINATIONS = (25, 10, 5)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = {c: 0 for c in self.DENOMINATIONS}
        for coin, count in dict(coins).items():
            if coin in self._inventory:
                self._inventory[coin] += int(count)
        self._inserted = []
        self._balance = 0

    def insert(self, coin):
        if coin not in self.DENOMINATIONS:
            return False
        self._inserted.append(coin)
        self._balance += coin
        return True

    def balance(self):
        return self._balance

    def _min_change(self, amount, pool):
        best = None
        max_q = min(pool[25], amount // 25)
        for q in range(max_q, -1, -1):
            rem1 = amount - 25 * q
            max_d = min(pool[10], rem1 // 10)
            for d in range(max_d, -1, -1):
                rem2 = rem1 - 10 * d
                if rem2 % 5 == 0 and rem2 // 5 <= pool[5]:
                    fives = rem2 // 5
                    total = q + d + fives
                    if best is None or total < best[0]:
                        best = (total, q, d, fives)
        if best is None:
            return None
        _, q, d, f = best
        return [25] * q + [10] * d + [5] * f

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        if self._balance < price:
            return 'INSUFFICIENT'

        change_amount = self._balance - price

        # Inserted coins count toward change, so build the pool from
        # the existing inventory plus the coins inserted for this purchase.
        pool = dict(self._inventory)
        for coin in self._inserted:
            pool[coin] += 1

        change = self._min_change(change_amount, pool)
        if change is None:
            return 'NO_CHANGE'

        for coin in change:
            pool[coin] -= 1

        self._inventory = pool
        self._inserted = []
        self._balance = 0
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        self._balance = 0
        return returned

from collections import Counter

ACCEPTED_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = Counter({c: n for c, n in dict(coins).items() if n > 0})
        self._inserted = []

    def insert(self, coin):
        if coin not in ACCEPTED_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'

        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        change_due = bal - price
        pool = Counter(self._inventory)
        pool.update(self._inserted)

        change = self._make_change(change_due, pool)
        if change is None:
            return 'NO_CHANGE'

        pool.subtract(Counter(change))
        self._inventory = Counter({c: n for c, n in pool.items() if n > 0})
        self._inserted = []
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    @staticmethod
    def _make_change(amount, inventory):
        # best maps reachable total -> (coin_count, tuple_of_coins), minimal count
        best = {0: (0, ())}
        for denom, n in inventory.items():
            if n <= 0:
                continue
            new = dict(best)
            for total, (count, coins) in best.items():
                for k in range(1, n + 1):
                    t = total + k * denom
                    if t > amount:
                        break
                    cand = (count + k, coins + (denom,) * k)
                    if t not in new or cand[0] < new[t][0]:
                        new[t] = cand
            best = new

        if amount not in best:
            return None
        return sorted(best[amount][1], reverse=True)

class VendingMachine:
    VALID_COINS = (5, 10, 25)

