        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        change_amount = bal - price

        # Available coins = machine inventory plus coins the customer inserted
        avail = dict(self._coins)
        for c in self._inserted:
            avail[c] += 1

        change_counts = self._make_change(change_amount, avail)
        if change_counts is None:
            return 'NO_CHANGE'

        # Update machine inventory: add inserted coins, remove returned change
        for c in self._inserted:
            self._coins[c] += 1
        for c, n in change_counts.items():
            self._coins[c] -= n

        self._inserted = []

        change = []
        for c in sorted(self.VALID_COINS, reverse=True):
            change.extend([c] * change_counts[c])
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    def _make_change(self, amount, avail):
        """Return dict of coin counts using the fewest coins, or None if impossible."""
        best = None
        max25 = min(avail[25], amount // 25)
        for a25 in range(max25, -1, -1):
            rem1 = amount - 25 * a25
            max10 = min(avail[10], rem1 // 10)
            for a10 in range(max10, -1, -1):
                rem2 = rem1 - 10 * a10
                if rem2 % 5 != 0:
                    continue
                a5 = rem2 // 5
                if a5 > avail[5]:
                    continue
                total = a25 + a10 + a5
                if best is None or total < best[0]:
                    best = (total, {25: a25, 10: a10, 5: a5})
        return None if best is None else best[1]

def evaluate(expr):
    """
    Evaluate an integer arithmetic expression.

    Supported operators: + - * / % ^ (unary minus), and parentheses.

    Semantics:
    - Precedence (lowest to highest): + -, then * / %, then unary -, then ^.
      So -2^2 == -4, and 2^3^2 == 2^(3^2) == 512 (^ is right-associative).
    - / and % truncate toward zero (C-style). The remainder takes the sign
      of the dividend: -7 % 3 == -1, 7 % -3 == 1.
    - Division or modulo by zero raises ZeroDivisionError.
    - Any negative exponent raises ValueError, for every base
      (so 2^-1, 1^-1, and 0^-1 all raise ValueError).
    - 0^0 == 1.
    - Malformed input (bad characters, unbalanced parentheses, missing
      operands, trailing tokens, empty input) raises SyntaxError.
    """

    # ---------- Tokenizer ----------
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append((c, c))
            i += 1
        else:
            raise SyntaxError(f"Unexpected character {c!r} at position {i}")

    # ---------- Recursive-descent parser / evaluator ----------
    class _Parser:
        def __init__(self, toks):
            self.toks = toks
            self.pos = 0

        def peek(self):
            if self.pos < len(self.toks):
                return self.toks[self.pos][0]
            return None

        def advance(self):
            tok = self.toks[self.pos]
            self.pos += 1
            return tok

        def parse(self):
            if not self.toks:
                raise SyntaxError("Empty expression")
            value = self.expr()
            if self.pos != len(self.toks):
                raise SyntaxError(
                    f"Unexpected token {self.toks[self.pos][1]!r}"
                )
            return value

        # expr := term (('+' | '-') term)*
        def expr(self):
            value = self.term()
            while self.peek() in ('+', '-'):
                op = self.advance()[0]
                rhs = self.term()
                value = value + rhs if op == '+' else value - rhs
            return value

        # term := unary (('*' | '/' | '%') unary)*
        def term(self):
            value = self.unary()
            while self.peek() in ('*', '/', '%'):
                op = self.advance()[0]
                rhs = self.unary()
                if op == '*':
                    value = value * rhs
                elif op == '/':
                    value = _trunc_div(value, rhs)
                else:
                    value = _trunc_mod(value, rhs)
            return value

        # unary := '-' unary | power
        def unary(self):
            if self.peek() == '-':
                self.advance()
                return -self.unary()
            return self.power()

        # power := atom ('^' unary)?   (right-associative; exponent may be unary)
        def power(self):
            base = self.atom()
            if self.peek() == '^':
                self.advance()
                exponent = self.unary()
                return _checked_pow(base, exponent)
            return base

        # atom := NUM | '(' expr ')'
        def atom(self):
            kind = self.peek()
            if kind == 'NUM':
                return self.advance()[1]
            if kind == '(':
                self.advance()
                value = self.expr()
                if self.peek() != ')':
                    raise SyntaxError("Expected ')'")
                self.advance()
                return value
            if kind is None:
                raise SyntaxError("Unexpected end of expression")
            raise SyntaxError(f"Unexpected token {self.toks[self.pos][1]!r}")

    def _trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def _trunc_mod(a, b):
        if b == 0:
            raise ZeroDivisionError("modulo by zero")
        r = abs(a) % abs(b)
        return r if a >= 0 else -r

    def _checked_pow(base, exponent):
        if exponent < 0:
            raise ValueError("negative exponents are not supported")
        return base ** exponent

    return _Parser(tokens).parse()

