class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._coins = {c: n for c, n in dict(coins).items() if n > 0}
        self._inserted = []
        self._balance = 0

    def insert(self, coin):
        if coin not in self.ACCEPTED_COINS:
            return False
        self._inserted.append(coin)
        self._balance += coin
        return True

    def balance(self):
        return self._balance

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        self._balance = 0
        return returned

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        if self._balance < price:
            return 'INSUFFICIENT'

        due = self._balance - price

        # Coins inserted in this transaction are usable as change.
        available = dict(self._coins)
        for c in self._inserted:
            available[c] = available.get(c, 0) + 1

        change = self._make_change(due, available)
        if change is None:
            return 'NO_CHANGE'

        # Commit the transaction: inserted coins join inventory, change leaves it.
        for c in self._inserted:
            self._coins[c] = self._coins.get(c, 0) + 1
        for c in change:
            self._coins[c] -= 1
        self._coins = {c: n for c, n in self._coins.items() if n > 0}

        self._inserted = []
        self._balance = 0
        return change

    @staticmethod
    def _make_change(amount, available):
        """Return a list of coins summing to amount using the fewest coins
        from `available` (coin -> count), or None if impossible."""
        if amount == 0:
            return []

        INF = float('inf')
        denoms = sorted(d for d, n in available.items() if n > 0 and d > 0)

        best = [INF] * (amount + 1)
        best[0] = 0
        layers = []

        for d in denoms:
            n = available[d]
            new = [INF] * (amount + 1)
            pick = [0] * (amount + 1)
            for a in range(amount + 1):
                for k in range(0, min(n, a // d) + 1):
                    prev = best[a - k * d]
                    if prev == INF:
                        continue
                    if prev + k < new[a]:
                        new[a] = prev + k
                        pick[a] = k
            layers.append(pick)
            best = new

        if best[amount] == INF:
            return None

        change = []
        a = amount
        for d, pick in reversed(list(zip(denoms, layers))):
            k = pick[a]
            change.extend([d] * k)
            a -= k * d
        return change

class ParseError(Exception):
    def __init__(self, message, pos):
