        self._transaction = []  # coins inserted in the current transaction

    def insert(self, coin):
        if coin not in VALID_COINS:
            return False
        self._transaction.append(coin)
        return True

    def balance(self):
        return sum(self._transaction)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'

        price = self._prices[item]
        balance = self.balance()
        if balance < price:
            return 'INSUFFICIENT'

        change_due = balance - price

        # Coins available for change include those inserted in this transaction.
        available = Counter(self._inventory)
        available.update(self._transaction)

        change = self._fewest_coins(change_due, available)
        if change is None:
            return 'NO_CHANGE'

        # Complete the purchase: inserted coins join the inventory, change leaves it.
        self._inventory.update(self._transaction)
        self._inventory.subtract(Counter(change))
        self._inventory = Counter({c: n for c, n in self._inventory.items() if n > 0})
        self._transaction = []
        return change

    def cancel(self):
        returned = list(self._transaction)
        self._transaction = []
        return returned

    @staticmethod
    def _fewest_coins(amount, available):
        """Return the fewest coins (as a descending list) summing to amount
        using at most the available counts, or None if impossible."""
        if amount == 0:
            return []

        n25 = available.get(25, 0)
        n10 = available.get(10, 0)
        n5 = available.get(5, 0)

        best = None
        best_combo = None
        for c25 in range(min(n25, amount // 25) + 1):
            rem25 = amount - 25 * c25
            for c10 in range(min(n10, rem25 // 10) + 1):
                rem = rem25 - 10 * c10
                if rem % 5 != 0:
                    continue
                c5 = rem // 5
                if c5 > n5:
                    continue
                total = c25 + c10 + c5
                if best is None or total < best:
                    best = total
                    best_combo = (c25, c10, c5)

        if best_combo is None:
            return None

        c25, c10, c5 = best_combo
        return [25] * c25 + [10] * c10 + [5] * c5

