from collections import Counter

ACCEPTED_COINS = (5, 10, 25)


def _fewest_coins(amount, available):
    """Return the fewest coins (as a list) summing to amount using at most
    available[d] coins of each denomination d, or None if impossible."""
    denoms = sorted(available, reverse=True)
    best = None

    def search(index, remaining, chosen):
        nonlocal best
        if best is not None and len(chosen) >= len(best):
            return
        if index == len(denoms):
            if remaining == 0:
                best = list(chosen)
            return
        d = denoms[index]
        max_count = min(available[d], remaining // d)
        for k in range(max_count, -1, -1):
            search(index + 1, remaining - k * d, chosen + [d] * k)

    search(0, amount, [])
    return best


class VendingMachine:
    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = Counter(
            {c: n for c, n in dict(coins).items() if c in ACCEPTED_COINS and n > 0}
        )
        self._transaction = []  # coins inserted in the current transaction, in order
        self._balance = 0

    def insert(self, coin):
        if coin not in ACCEPTED_COINS:
            return False
        self._transaction.append(coin)
        self._balance += coin
        return True

    def balance(self):
        return self._balance

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'

        price = self._prices[item]
        if self._balance < price:
            return 'INSUFFICIENT'

        change_due = self._balance - price

        # Coins inserted in this transaction are available for making change.
        available = Counter(self._inventory)
        available.update(self._transaction)
        available = {d: n for d, n in available.items() if n > 0}

        change = _fewest_coins(change_due, available)
        if change is None:
            return 'NO_CHANGE'

        remaining = Counter(available)
        remaining.subtract(change)
        self._inventory = Counter({d: n for d, n in remaining.items() if n > 0})

        self._transaction = []
        self._balance = 0
        return change

    def cancel(self):
        returned = list(self._transaction)
        self._transaction = []
        self._balance = 0
        return returned

