            return False
        # Next booking overlaps if it starts before our end.
        if i < len(self._intervals) and self._intervals[i][0] < end:
            return False
        self._intervals.insert(i, (start, end))
        return True

    def cancel(self, start, end):
        """Cancel the booking exactly matching [start, end).

        Return True if it was found and removed, False otherwise.
        """
        i = bisect_left(self._intervals, (start, end))
        if i < len(self._intervals) and self._intervals[i] == (start, end):
            del self._intervals[i]
            return True
        return False

    def bookings(self):
        """Return a sorted list of (start, end) tuples for all current bookings."""
        return list(self._intervals)

    def free_slots(self, lo, hi, min_len=1):
        """Return the free gaps within the window [lo, hi).

        Each gap is a (start, end) tuple with length >= min_len. Gaps are
        returned in sorted order.
        """
        if not lo < hi:
            raise ValueError(f"invalid window: lo={lo!r} must be < hi={hi!r}")

        gaps = []
        cursor = lo
        for s, e in self._intervals:
            if e <= lo:
                continue
            if s >= hi:
                break
            if s > cursor:
                gaps.append((cursor, s))
            if e > cursor:
                cursor = e
        if cursor < hi:
            gaps.append((cursor, hi))

        return [(a, b) for a, b in gaps if b - a >= min_len]

