    Bookings are stored as a sorted list of non-overlapping (start, end)
    tuples. Two intervals overlap when they share at least one instant, so
    [1, 3) and [3, 5) do not overlap and may both be booked.
    """

    def __init__(self):
        self._bookings = []  # sorted list of (start, end), non-overlapping

    @staticmethod
    def _validate(start, end):
        if start >= end:
            raise ValueError(f"invalid interval [{start}, {end}): start must be < end")

    def book(self, start, end):
        """Book [start, end). Returns False if it overlaps an existing booking."""
        self._validate(start, end)
        idx = bisect.bisect_left(self._bookings, (start, end))

        # The booking just before idx may extend past our start.
        if idx > 0 and self._bookings[idx - 1][1] > start:
            return False
        # The booking at idx may start before our end.
        if idx < len(self._bookings) and self._bookings[idx][0] < end:
            return False

        self._bookings.insert(idx, (start, end))
        return True

    def cancel(self, start, end):
        """Cancel an existing booking that exactly matches [start, end).

        Returns True if a matching booking was removed, False otherwise.
        """
        self._validate(start, end)
        idx = bisect.bisect_left(self._bookings, (start, end))
        if idx < len(self._bookings) and self._bookings[idx] == (start, end):
            del self._bookings[idx]
            return True
        return False

    def bookings(self):
        """Return a sorted list of (start, end) tuples for all bookings."""
        return list(self._bookings)

    def free_slots(self, lo, hi, min_len=1):
        """Return the free gaps inside the window [lo, hi).

        Each gap is a (start, end) tuple with length >= min_len. Gaps are
        returned sorted by start time.
        """
        if lo > hi:
            raise ValueError(f"invalid window [{lo}, {hi}): lo must be <= hi")
        if min_len <= 0:
            raise ValueError("min_len must be positive")

        free = []
        cur = lo  # start of the current candidate gap
        for s, e in self._bookings:
            if e <= cur:
                continue  # booking ends before the current position
            if s >= hi:
                break  # all remaining bookings start at or after the window end
            if s > cur and s - cur >= min_len:
                free.append((cur, s))
            cur = max(cur, e)
            if cur >= hi:
                break

        if cur < hi and hi - cur >= min_len:
            free.append((cur, hi))
        return free

