def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines (lines containing
    only whitespace). Each paragraph is wrapped independently, and the
    wrapped paragraphs are joined with a single blank line. Words longer
    than width are split into chunks of at most width characters.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    wrapped_paragraphs = []
    for paragraph in re.split(r"\n\s*\n", text):
        words = paragraph.split()
        if not words:
            continue

        lines = []
        current = ""
        for word in words:
            if len(word) > width:
                if current:
                    lines.append(current)
                    current = ""
                pieces = [word[i:i + width] for i in range(0, len(word), width)]
                lines.extend(pieces[:-1])
                current = pieces[-1]
            elif not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

        if current:
            lines.append(current)

        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)

