    return order


def _find_cycle(graph, remaining):
    """Extract one concrete cycle from the nodes Kahn's algorithm could not place."""
    unresolved = {node for node, count in remaining.items() if count > 0}
    # Every unresolved node has at least one unresolved dependency, so
    # following dependencies from any unresolved node must eventually revisit
    # a node, which closes a cycle.
    start = min(unresolved)
    path = []
    index = {}
    node = start
    while node not in index:
        index[node] = len(path)
        path.append(node)
        node = min(d for d in graph[node] if d in unresolved)
    cycle = path[index[node]:] + [node]
    return cycle

import re


def wrap_text(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = re.split(r"\n\s*\n", text)
    blocks = []

    for para in paragraphs:
        words = para.split()
        if not words:
            continue

        lines = []
        current = ""

        for word in words:
            if len(word) > width:
                # Flush the current line, then hard-split the overlong word.
                if current:
                    lines.append(current)
                    current = ""
                chunks = [word[i:i + width] for i in range(0, len(word), width)]
                lines.extend(chunks[:-1])
                # The final piece starts the line that following words fill.
                current = chunks[-1]
            elif not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

        if current:
            lines.append(current)

        blocks.append("\n".join(lines))

    return "\n\n".join(blocks)

