class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(self.cycle))


def topo_order(deps):
    graph = {}
    for pkg, reqs in deps.items():
        graph.setdefault(pkg, set())
        for r in reqs:
            graph[pkg].add(r)
            graph.setdefault(r, set())

    # Detect cycles with DFS so the error can report the actual cycle.
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}
    for start in sorted(graph):
        if color[start] != WHITE:
            continue
        color[start] = GRAY
        path = [start]
        stack = [iter(sorted(graph[start]))]
        while stack:
            nxt = next(stack[-1], None)
            if nxt is None:
                stack.pop()
                color[path.pop()] = BLACK
                continue
            if color[nxt] == GRAY:
                idx = path.index(nxt)
                raise CycleError(path[idx:] + [nxt])
            if color[nxt] == WHITE:
                color[nxt] = GRAY
                path.append(nxt)
                stack.append(iter(sorted(graph[nxt])))

    # Kahn's algorithm with a min-heap for alphabetical tie-breaking.
    remaining = {n: len(graph[n]) for n in graph}
    dependents = {n: [] for n in graph}
    for n, reqs in graph.items():
        for r in reqs:
            dependents[r].append(n)

    heap = [n for n, c in remaining.items() if c == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for d in dependents[n]:
            remaining[d] -= 1
            if remaining[d] == 0:
                heapq.heappush(heap, d)

    return order

