    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle detected: " + " -> ".join(self.cycle))


def _find_cycle(graph, nodes):
    """Return one cycle as a list like [a, b, ..., a], or [] if none is found."""
    state = {}  # 1 = on current DFS path, 2 = fully explored
    path = []

    def visit(node):
        state[node] = 1
        path.append(node)
        for dep in sorted(graph[node]):
            if state.get(dep) == 1:
                start = path.index(dep)
                return path[start:] + [dep]
            if dep not in state:
                found = visit(dep)
                if found:
                    return found
        path.pop()
        state[node] = 2
        return None

    for node in sorted(nodes):
        if node not in state:
            found = visit(node)
            if found:
                return found
    return []


def topo_order(deps):
    """
    Return an install order for the packages in ``deps``, where ``deps`` maps
    each package to a list of its dependencies. Dependencies come before the
    packages that need them; ties are broken alphabetically.

    Dependencies that do not appear as keys are treated as packages with no
    dependencies of their own.

    Raises CycleError (with a ``.cycle`` list) if the graph contains a cycle.
    """
    graph = {}
    for pkg, reqs in deps.items():
        graph.setdefault(pkg, set())
        for req in reqs:
            graph[pkg].add(req)
            graph.setdefault(req, set())

    remaining = {node: len(reqs) for node, reqs in graph.items()}
    dependents = {node: [] for node in graph}
    for node, reqs in graph.items():
        for req in reqs:
            dependents[req].append(node)

    ready = [node for node, count in remaining.items() if count == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(graph):
        done = set(order)
        unresolved = [node for node in graph if node not in done]
        raise CycleError(_find_cycle(graph, unresolved))

    return order

class Editor:
    def __init__(self, text: str = ""):
        self._text = text
        self._cursor = len(text)
        self._undo_stack = []
        self._redo_stack = []

    @property
    def text(self) -> str:
        return self._text

    @property
    def cursor(self) -> int:
        return self._cursor

    def _snapshot(self):
        return (self._text, self._cursor)

    def _restore(self, snapshot):
        self._text, self._cursor = snapshot

    def _commit(self, before):
        """Record `before` in history if the state actually changed."""
        if (self._text, self._cursor) != before:
            self._undo_stack.append(before)
            self._redo_stack.clear()

    def insert(self, s: str) -> None:
        """Insert `s` at the cursor and advance the cursor past it."""
        if not s:
            return
        before = self._snapshot()
        c = self._cursor
        self._text = self._text[:c] + s + self._text[c:]
        self._cursor = c + len(s)
        self._commit(before)

    def delete(self, n: int = 1) -> None:
        """Backspace: delete up to `n` characters before the cursor."""
        if n <= 0 or self._cursor == 0:
            return
        before = self._snapshot()
        count = min(n, self._cursor)
        c = self._cursor
        self._text = self._text[:c - count] + self._text[c:]
        self._cursor = c - count
        self._commit(before)

    def move(self, pos: int) -> None:
        """Move the cursor to `pos`, clamped to the valid range [0, len(text)]."""
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        """Revert the last edit. Returns True if anything was undone."""
        if not self._undo_stack:
            return False
        self._redo_stack.append(self._snapshot())
        self._restore(self._undo_stack.pop())
        return True

    def redo(self) -> bool:
        """Reapply the last undone edit. Returns True if anything was redone."""
        if not self._redo_stack:
            return False
        self._undo_stack.append(self._snapshot())
        self._restore(self._redo_stack.pop())
        return True

import heapq


class CycleError(Exception):
    """Raised when the dependency graph contains a cycle.

    The ``cycle`` attribute is a list of package names forming the cycle,
    where each package depends on the next one and the last element equals
    the first (e.g. ``['a', 'b', 'a']`` means a -> b -> a).
    """

    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(map(str, self.cycle)))


def topo_order(deps):
    """Return an install order (dependencies first) for ``deps``.

    ``deps`` maps each package to a list of its dependencies. Packages that
    appear only as dependencies are included in the result. Ties are broken
    alphabetically. Raises ``CycleError`` if the graph contains a cycle.
    """
    # Build the full graph, including packages that only appear as dependencies.
    graph = {}
    for pkg, reqs in deps.items():
        graph.setdefault(pkg, set()).update(reqs)
        for req in reqs:
            graph.setdefault(req, set())

    # dependents[x] = packages that directly depend on x
    dependents = {node: [] for node in graph}
    indegree = {}
    for node, reqs in graph.items():
        indegree[node] = len(reqs)
        for req in reqs:
            dependents[req].append(node)

    # Kahn's algorithm with a min-heap for alphabetical tie-breaking.
    ready = [node for node in graph if indegree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(graph):
        # Every unordered node still has an unordered dependency, so walking
        # dependencies within the remaining set must eventually revisit a node.
        remaining = {node for node in graph if indegree[node] > 0}
        path = []
        seen = {}
        node = min(remaining)
        while node not in seen:
            seen[node] = len(path)
            path.append(node)
            node = min(d for d in graph[node] if d in remaining)
        cycle = path[seen[node]:] + [node]
        raise CycleError(cycle)

    return order

