        s = str(s)
        if not s:
            return
        before = self._snapshot()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)
        self._record(before)

    def delete(self, n=1):
        """Backspace: delete up to n characters before the cursor."""
        if n <= 0 or self._cursor == 0:
            return
        n = min(n, self._cursor)
        before = self._snapshot()
        start = self._cursor - n
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start
        self._record(before)

    def move(self, pos):
        self._cursor = max(0, min(int(pos), len(self._text)))

    def undo(self):
        if not self._undo_stack:
            return False
        self._redo_stack.append(self._snapshot())
        self._restore(self._undo_stack.pop())
        return True

    def redo(self):
        if not self._redo_stack:
            return False
        self._undo_stack.append(self._snapshot())
        self._restore(self._redo_stack.pop())
        return True

