    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version):
    """Parse a SemVer 2.0.0 string into (major, minor, patch, prerelease_identifiers).

    Build metadata is validated but does not affect precedence.
    Raises ValueError for invalid versions.
    """
    if not isinstance(version, str):
        raise ValueError(f"invalid semantic version: {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"invalid semantic version: {version!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre = match.group(4)
    prerelease = tuple(pre.split(".")) if pre is not None else ()
    return major, minor, patch, prerelease


def _compare_identifiers(x, y):
    x_numeric = x.isdigit()
    y_numeric = y.isdigit()
    if x_numeric and y_numeric:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_numeric:
        return -1  # numeric identifiers have lower precedence
    if y_numeric:
        return 1
    return (x > y) - (x < y)  # ASCII lexical comparison


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1  # a normal version has higher precedence than a pre-release
    if not b:
        return -1
    for x, y in zip(a, b):
        result = _compare_identifiers(x, y)
        if result:
            return result
    return (len(a) > len(b)) - (len(a) < len(b))


def compare_versions(a, b):
    """Compare two semantic versions by SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b (in precedence), and 1 if a > b.
    Raises ValueError if either version is invalid.
    """
    a_major, a_minor, a_patch, a_pre = _parse(a)
    b_major, b_minor, b_patch, b_pre = _parse(b)

    for x, y in ((a_major, b_major), (a_minor, b_minor), (a_patch, b_patch)):
        if x != y:
            return -1 if x < y else 1

    result = _compare_prerelease(a_pre, b_pre)
    if result < 0:
        return -1
    if result > 0:
        return 1
    return 0


def sort_versions(versions):
    """Return a new list of semantic version strings sorted by SemVer 2.0.0 precedence.

    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for version in versions:
        _parse(version)  # validate all entries up front
    return sorted(versions, key=cmp_to_key(compare_versions))

import re


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by blank lines and remain separated in the
    output. Words longer than width are broken at the width limit, and the
    final fragment of a broken word is packed greedily with the words that
    follow it.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = []
    for para in re.split(r'\n\s*\n', text):
        words = para.split()
        if not words:
            continue

        lines = []
        current = ""
        for word in words:
            if len(word) > width:
                # A long word cannot share a line with anything before it.
                if current:
                    lines.append(current)
                    current = ""
                # Break the word at the width limit.
                while len(word) > width:
                    lines.append(word[:width])
                    word = word[width:]
                # The remaining fragment (1..width chars) starts the next line
                # and can still pack greedily with following words.
                current = word
                continue

            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

        if current:
            lines.append(current)

        paragraphs.append("\n".join(lines))

    return "\n\n".join(paragraphs)

