def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by blank lines and kept separate in the output.
    Words longer than width are hard-broken into chunks of at most width
    characters, and each fragment takes part in the greedy packing.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = re.split(r"\n\s*\n", text)
    out = []

    for para in paragraphs:
        words = para.split()
        if not words:
            continue

        lines = []
        cur = ""
        for word in words:
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            for piece in pieces:
                if not cur:
                    cur = piece
                elif len(cur) + 1 + len(piece) <= width:
                    cur += " " + piece
                else:
                    lines.append(cur)
                    cur = piece
        if cur:
            lines.append(cur)

        out.append("\n".join(lines))

    return "\n\n".join(out)

